function normalize(s) { return s.toLowerCase().replace(/[\s.\-_]/g, ''); }
function getByKey(key) { return FLAT.find(x => x.key === key); }

function renderTroubleshoot(detailKey) {
  let data = TROUBLESHOOT[detailKey];
  let redirectNote = '';
  let seenKeys = [];
  while (data && data.seeAlso && !data.steps) {
    seenKeys.push(detailKey);
    if (seenKeys.includes(data.seeAlso)) break;
    redirectNote = `<p class="ts-seealso">※ [AL.${escapeHtml(data.seeAlso)}]과 동일한 점검 순서입니다.</p>`;
    detailKey = data.seeAlso;
    data = TROUBLESHOOT[detailKey];
  }

  if (!data || !data.steps) {
    return `
      <div class="placeholder-body">
        <p>이 항목은 아직 데이터화되지 않았습니다. (1장 알람·경고·코드 없는 트러블, 2장 컨버터 유닛(2-1~2-10)은 전체 반영 완료, 3장 이후는 추후 반영 예정)</p>
        <p class="placeholder-ref">참고: MR-J4 트러블슈팅 매뉴얼 Ver.J</p>
      </div>`;
  }

  const targetHtml = data.target && data.target.length
    ? `<div class="ts-target">대상 기종: ${data.target.map(escapeHtml).join(', ')}</div>`
    : '';

  const stepsHtml = data.steps.map(s => {
    const branchesHtml = (s.branches || []).map(b => `
      <div class="ts-branch">
        <div class="ts-branch-result">${escapeHtml(b.result)}</div>
        <div class="ts-branch-arrow">→</div>
        <div class="ts-branch-action">${escapeHtml(b.action)}</div>
      </div>`).join('');
    const stepTarget = s.target && s.target.length
      ? `<div class="ts-target">해당: ${s.target.map(escapeHtml).join(', ')}</div>` : '';
    return `
      <div class="ts-step">
        <div class="ts-step-head">
          <span class="ts-step-no">(${s.no})</span>
          <span class="ts-cause">${escapeHtml(s.cause)}</span>
        </div>
        <div class="ts-check">${escapeHtml(s.check)}</div>
        ${stepTarget}
        <div class="ts-branches">${branchesHtml}</div>
      </div>`;
  }).join('');

  return `${redirectNote}${targetHtml}${stepsHtml}`;
}

const searchInput = document.getElementById('searchInput');
const alarmList = document.getElementById('alarmList');
const emptyState = document.getElementById('emptyState');
const resultCount = document.getElementById('resultCount');
const clearBtn = document.getElementById('clearBtn');

function renderList(query) {
  const q = normalize(query || '');
  let items;
  if (!q) {
    items = [];
  } else {
    items = FLAT.filter(it => it.searchBlob.includes(q));
    items.sort((a, b) => {
      const aExact = a.groupNo.toLowerCase() === q || a.detail.toLowerCase().replace(/[.\-]/g,'') === q;
      const bExact = b.groupNo.toLowerCase() === q || b.detail.toLowerCase().replace(/[.\-]/g,'') === q;
      if (aExact && !bExact) return -1;
      if (bExact && !aExact) return 1;
      return 0;
    });
  }

  alarmList.innerHTML = '';
  if (q && items.length === 0) {
    emptyState.classList.remove('hidden');
    resultCount.textContent = '';
  } else {
    emptyState.classList.add('hidden');
    resultCount.textContent = q ? (items.length + '건 검색됨') : '';
    items.slice(0, 80).forEach(it => alarmList.appendChild(renderCard(it)));
  }

  document.getElementById('favSection').classList.toggle('hidden', !!q || favorites.length === 0);
  document.getElementById('recentSection').classList.toggle('hidden', !!q || recent.length === 0);

  if (!q) renderChips();
}

function renderCard(it) {
  const card = document.createElement('button');
  card.className = 'alarm-card';
  card.dataset.key = it.key;
  if (it.kind === 'nocode') {
    card.innerHTML = `
      <div class="alarm-card-code">1.6</div>
      <div class="alarm-card-main">
        <div class="alarm-card-title">${escapeHtml(it.detailName)}</div>
        <div class="alarm-card-sub">코드 없는 트러블</div>
      </div>
      <div class="alarm-card-tag tag-NOCODE">증상별</div>
    `;
    card.addEventListener('click', () => openDetail(it.key));
    return card;
  }
  if (it.kind === 'conv_alarm' || it.kind === 'conv_warning') {
    card.innerHTML = `
      <div class="alarm-card-code">AL.${escapeHtml(it.detail)}</div>
      <div class="alarm-card-main">
        <div class="alarm-card-title">${escapeHtml(it.detailName)}</div>
        <div class="alarm-card-sub">2장 컨버터 유닛</div>
      </div>
      <div class="alarm-card-tag ${it.kind === 'conv_alarm' ? 'tag-CONV' : 'tag-CONVWARN'}">${it.kind === 'conv_alarm' ? '컨버터 알람' : '컨버터 경고'}</div>
    `;
    card.addEventListener('click', () => openDetail(it.key));
    return card;
  }
  const stopInfo = STOP_LABEL[it.stop] || { label: it.stop, desc: '' };
  card.innerHTML = `
    <div class="alarm-card-code">AL.${escapeHtml(it.detail)}</div>
    <div class="alarm-card-main">
      <div class="alarm-card-title">${escapeHtml(it.detailName)}</div>
      <div class="alarm-card-sub">${escapeHtml(it.groupName)}</div>
    </div>
    <div class="alarm-card-tag tag-${escapeHtml(it.stop)}">${escapeHtml(stopInfo.label)}</div>
  `;
  card.addEventListener('click', () => openDetail(it.key));
  return card;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function renderChips() {
  const favChips = document.getElementById('favChips');
  const recentChips = document.getElementById('recentChips');
  favChips.innerHTML = '';
  recentChips.innerHTML = '';
  favorites.forEach(key => { const it = getByKey(key); if (it) favChips.appendChild(makeChip(it)); });
  recent.filter(k => !favorites.includes(k)).forEach(key => { const it = getByKey(key); if (it) recentChips.appendChild(makeChip(it)); });
}

function makeChip(it) {
  const chip = document.createElement('button');
  chip.className = 'chip';
  chip.textContent = it.kind === 'nocode' ? it.detailName.slice(0, 10) : ('AL.' + it.detail);
  chip.addEventListener('click', () => openDetail(it.key));
  return chip;
}

function addRecent(key) {
  recent = [key, ...recent.filter(k => k !== key)].slice(0, 10);
  saveJSON(STORAGE_KEY_RECENT, recent);
}

function toggleFavorite(key) {
  if (favorites.includes(key)) favorites = favorites.filter(k => k !== key);
  else favorites = [key, ...favorites].slice(0, 20);
  saveJSON(STORAGE_KEY_FAV, favorites);
}

const detailOverlay = document.getElementById('detailOverlay');
const detailBody = document.getElementById('detailBody');
const toggleFavBtn = document.getElementById('toggleFav');
let currentDetailKey = null;

function renderNocodeDetail(it) {
  const nc = NOCODE_DATA.items.find(x => x.id === it.key);
  const online = navigator.onLine !== false;
  const causesHtml = nc ? nc.causes.map((c, i) => {
    const targetHtml = c.target && c.target.length
      ? `<div class="ts-target">대상 기종: ${c.target.map(escapeHtml).join(', ')}</div>` : '';
    const checksHtml = c.checks.map(k => `
      <div class="ts-branch">
        <div class="ts-branch-result">${escapeHtml(k.investigation)}</div>
        <div class="ts-branch-arrow">→</div>
        <div class="ts-branch-action">${escapeHtml(k.treatment)}</div>
      </div>`).join('');
    return `
      <div class="ts-step">
        <div class="ts-step-head">
          <span class="ts-step-no">(${i + 1})</span>
          <span class="ts-cause">${escapeHtml(c.cause)}</span>
        </div>
        ${targetHtml}
        <div class="ts-branches">${checksHtml}</div>
      </div>`;
  }).join('') : '<div class="placeholder-body"><p>데이터를 찾을 수 없습니다.</p></div>';

  detailBody.innerHTML = `
    <div class="detail-code">1.6 코드 없는 트러블</div>
    <h2 class="detail-title">${escapeHtml(it.detailName)}</h2>
    <div class="detail-group">서보앰프, 서보모터 및 엔코더가 고장났을 경우 이런 현상이 발생할 수 있습니다.</div>

    <div class="detail-block">
      <div class="detail-block-label">추정 원인 &amp; 조사 결과 → 처치</div>
      ${causesHtml}
    </div>

    <div class="detail-block ai-block ${online ? '' : 'disabled'}">
      <div class="detail-block-label">매뉴얼 근거 기반 AI 질문</div>
      <div class="placeholder-body">
        <p>${online ? '온라인 상태입니다. (AI 질의 기능은 다음 단계에서 연결 예정)' : '오프라인 상태에서는 사용할 수 없습니다. 인터넷 연결 시 AI에게 추가 질문이 가능해질 예정입니다.'}</p>
      </div>
    </div>

    <div class="detail-block placeholder-block">
      <div class="detail-block-label">내 조치 이력</div>
      <div class="placeholder-body"><p>아직 기록된 이력이 없습니다. (이력 기능은 다음 단계에서 추가됩니다)</p></div>
    </div>
  `;
}

function renderConverterDetail(it) {
  const isAlarm = it.kind === 'conv_alarm';
  const src = isAlarm ? CONVERTER_ALARM_DATA : CONVERTER_WARNING_DATA;
  const info = src.items.find(x => x.code === it.detail);
  const online = navigator.onLine !== false;

  const resetList = isAlarm
    ? (it.reset && it.reset.length
        ? it.reset.map(r => `<span class="reset-pill">${escapeHtml(r)}</span>`).join('')
        : '<span class="reset-pill reset-none">해당 없음</span>')
    : '<span class="reset-pill reset-none">경고는 원인을 없애면 자동으로 해제됩니다</span>';

  const cautionHtml = info && info.cooling
    ? `<div class="detail-block">
         <div class="detail-block-label">⚠ 주의</div>
         <div class="stop-box tag-EDB">
           <strong>냉각 시간 필요</strong>
           <span>이 ${isAlarm ? '알람' : '경고'} 발생 시 전원을 반복하여 OFF/ON해 운전을 재개하지 마십시오. 컨버터 유닛, 드라이브 유닛 및 서보모터 고장의 원인이 됩니다. 발생 원인을 없애는 것과 동시에, 30분 이상의 냉각 시간을 가지고 나서 운전을 재개해 주십시오.</span>
         </div>
       </div>`
    : '';
  const noHistoryHtml = info && info.noHistory
    ? `<p class="ts-seealso">※ 이 알람은 알람 이력에 기록되지 않습니다.</p>` : '';

  detailBody.innerHTML = `
    <div class="detail-code">AL.${escapeHtml(it.detail)}</div>
    <h2 class="detail-title">${escapeHtml(it.detailName)}</h2>
    <div class="detail-group">제2장 MR-CR55K(4) 컨버터 유닛 ${isAlarm ? '알람' : '경고'}</div>

    ${info && info.desc ? `<div class="detail-block"><div class="detail-block-label">현상</div><div class="placeholder-body"><p>${escapeHtml(info.desc)}</p></div></div>` : ''}

    ${cautionHtml}

    <div class="detail-block">
      <div class="detail-block-label">해제(리셋) 방법</div>
      <div class="reset-row">${resetList}</div>
      ${noHistoryHtml}
    </div>

    <div class="detail-block ${TROUBLESHOOT[it.detail] ? '' : 'placeholder-block'}">
      <div class="detail-block-label">원인 &amp; 점검 순서</div>
      ${renderTroubleshoot(it.detail)}
    </div>

    <div class="detail-block ai-block ${online ? '' : 'disabled'}">
      <div class="detail-block-label">매뉴얼 근거 기반 AI 질문</div>
      <div class="placeholder-body">
        <p>${online ? '온라인 상태입니다. (AI 질의 기능은 다음 단계에서 연결 예정)' : '오프라인 상태에서는 사용할 수 없습니다. 인터넷 연결 시 AI에게 추가 질문이 가능해질 예정입니다.'}</p>
      </div>
    </div>

    <div class="detail-block placeholder-block">
      <div class="detail-block-label">내 조치 이력</div>
      <div class="placeholder-body"><p>아직 기록된 이력이 없습니다. (이력 기능은 다음 단계에서 추가됩니다)</p></div>
    </div>
  `;
}

function openDetail(key) {
  const it = getByKey(key);
  if (!it) return;
  currentDetailKey = key;
  addRecent(key);

  if (it.kind === 'nocode') {
    renderNocodeDetail(it);
    toggleFavBtn.textContent = favorites.includes(key) ? '★' : '☆';
    detailOverlay.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    return;
  }

  if (it.kind === 'conv_alarm' || it.kind === 'conv_warning') {
    renderConverterDetail(it);
    toggleFavBtn.textContent = favorites.includes(key) ? '★' : '☆';
    detailOverlay.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    return;
  }

  const stopInfo = STOP_LABEL[it.stop] || { label: it.stop, desc: '' };
  const resetList = it.reset && it.reset.length
    ? it.reset.map(r => `<span class="reset-pill">${escapeHtml(r)}</span>`).join('')
    : (it.kind === 'warning'
        ? '<span class="reset-pill reset-none">경고는 원인을 없애면 자동으로 해제됩니다</span>'
        : '<span class="reset-pill reset-none">해당 없음 (아래 참고)</span>');

  const online = navigator.onLine !== false;

  detailBody.innerHTML = `
    <div class="detail-code">AL.${escapeHtml(it.detail)}</div>
    <h2 class="detail-title">${escapeHtml(it.detailName)}</h2>
    <div class="detail-group">${escapeHtml(it.groupNo)}. ${escapeHtml(it.groupName)}</div>

    <div class="detail-block">
      <div class="detail-block-label">정지 방식</div>
      <div class="stop-box tag-${escapeHtml(it.stop)}">
        <strong>${escapeHtml(stopInfo.label)}</strong>
        <span>${escapeHtml(stopInfo.desc)}</span>
      </div>
    </div>

    <div class="detail-block">
      <div class="detail-block-label">해제(리셋) 방법</div>
      <div class="reset-row">${resetList}</div>
    </div>

    <div class="detail-block ${TROUBLESHOOT[it.detail] ? '' : 'placeholder-block'}">
      <div class="detail-block-label">원인 &amp; 점검 순서</div>
      ${renderTroubleshoot(it.detail)}
    </div>

    <div class="detail-block ai-block ${online ? '' : 'disabled'}">
      <div class="detail-block-label">매뉴얼 근거 기반 AI 질문</div>
      <div class="placeholder-body">
        <p>${online ? '온라인 상태입니다. (AI 질의 기능은 다음 단계에서 연결 예정)' : '오프라인 상태에서는 사용할 수 없습니다. 인터넷 연결 시 AI에게 추가 질문이 가능해질 예정입니다.'}</p>
      </div>
    </div>

    <div class="detail-block placeholder-block">
      <div class="detail-block-label">내 조치 이력</div>
      <div class="placeholder-body"><p>아직 기록된 이력이 없습니다. (이력 기능은 다음 단계에서 추가됩니다)</p></div>
    </div>
  `;

  toggleFavBtn.textContent = favorites.includes(key) ? '★' : '☆';
  detailOverlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeDetail() {
  detailOverlay.classList.add('hidden');
  document.body.style.overflow = '';
  renderList(searchInput.value);
}

document.getElementById('closeDetail').addEventListener('click', closeDetail);
detailOverlay.addEventListener('click', (e) => { if (e.target === detailOverlay) closeDetail(); });

toggleFavBtn.addEventListener('click', () => {
  if (!currentDetailKey) return;
  toggleFavorite(currentDetailKey);
  toggleFavBtn.textContent = favorites.includes(currentDetailKey) ? '★' : '☆';
});

document.getElementById('favBtn').addEventListener('click', () => {
  searchInput.value = '';
  renderList('');
  document.getElementById('favSection').scrollIntoView({ behavior: 'smooth' });
});

searchInput.addEventListener('input', (e) => {
  renderList(e.target.value);
  clearBtn.classList.toggle('hidden', !e.target.value);
});

clearBtn.addEventListener('click', () => {
  searchInput.value = '';
  renderList('');
  clearBtn.classList.add('hidden');
  searchInput.focus();
});

renderList('');
clearBtn.classList.add('hidden');

function updateOnlineStatus() {
  const banner = document.getElementById('offlineBanner');
  const statusLine = document.getElementById('statusLine');
  if (navigator.onLine === false) {
    banner.classList.remove('hidden');
    statusLine.textContent = '오프라인 모드 · 키워드 검색만 가능';
  } else {
    banner.classList.add('hidden');
    statusLine.textContent = '미쓰비시 서보앰프 알람 검색';
  }
}
window.addEventListener('online', updateOnlineStatus);
window.addEventListener('offline', updateOnlineStatus);
updateOnlineStatus();

// 표준 서비스워커 등록 (같은 origin의 실제 파일)
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch(() => {});
  });
}
